```r
library(plm)
library(imputeTS)

data <- read.csv("VS.csv", header = TRUE, check.names = FALSE)
data$time <- as.Date(data$time, "%Y/%m/%d")

vars <- c(
  "Qtrcret", "Qtrret", "Qtraret", "EVANetAssrt1", "EVATotAssrt1",
  "EVAps1", "EVArt1", "OpeEVArt1", "QtrFulTurnR", "PE", "PB", "PCF",
  "PS", "SN", "N10H", "IH", "LR", "LCR", "STD", "RF", "LNINC"
)

needed <- c("bankcode", "time", vars)
missing_cols <- setdiff(needed, names(data))
if (length(missing_cols)) {
  stop("数据中缺少这些列：", paste(missing_cols, collapse = ", "))
}

# 按银行和时间排序后，逐银行插值
data <- data[order(data$bankcode, data$time), ]

for (id in unique(data$bankcode)) {
  idx <- which(data$bankcode == id)

  for (v in vars) {
    x <- data[[v]][idx]
    if (!is.numeric(x)) stop("变量不是数值型：", v)

    if (anyNA(x)) {
      if (sum(!is.na(x)) >= 2) {
        data[[v]][idx] <- na_interpolation(x, option = "spline")
      } else {
        warning("银行 ", id, " 的变量 ", v,
                " 有效值少于 2 个，无法可靠进行样条插值。")
      }
    }
  }
}

panel_data <- pdata.frame(data, index = c("bankcode", "time"))
summary(panel_data)
write.csv(data, "ytcb.csv", row.names = FALSE)
```

若仍报错，请查看完整报错对应的行，并检查 `names(data)`。特别是变量名不匹配、列不是数值型，或某组数据可用观测过少，都可能导致插值失败。

